package br.com.trama.model;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="produto") public class Produto { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id_produto") private Long id; @Column(nullable=false,length=120) private String nome; @Column(length=500) private String descricao; @Column(nullable=false,precision=12,scale=2) private BigDecimal preco; @ManyToOne(optional=false,fetch=FetchType.LAZY) @JoinColumn(name="id_artesao",nullable=false) private Artesao artesao; public Produto(){} public Long getId(){return id;} public String getNome(){return nome;} public void setNome(String v){nome=v;} public String getDescricao(){return descricao;} public void setDescricao(String v){descricao=v;} public BigDecimal getPreco(){return preco;} public void setPreco(BigDecimal v){preco=v;} public Artesao getArtesao(){return artesao;} public void setArtesao(Artesao v){artesao=v;} }
